class IconChallenge
{
public:
    enum { MAX_SEQUENCE_SIZE = 10 };
    enum { MAX_ARRANGEMENT_SIZE = 10 };

    class Icon
    {
        char data[44];
    };

    class Task
    {
    public:
        enum TYPE
        {
            TYPE_AIR_FLIP,
            TYPE_AIR_GRAB,
            TYPE_AIR_SPIN,
            TYPE_AIR_POINTS_1000,
            TYPE_AIR_POINTS_2000,
            TYPE_AIR_POINTS_5000,
            TYPE_AIR_SPECIAL,
            TYPE_FACE_SPIN,
            TYPE_TUBE_TIME_10,
            TYPE_TUBE_TIME_15,
            TYPE_TUBE_TIME_30,
            TYPE_TUBE_TRICK,
            TYPE_NUM,
            TYPE_NONE,
        };
    };

    class Sequence
    {
        char data[168];

    public:
        void Reset(void);
        void PushTask(Icon *i, const Task::TYPE t);
    };

    class Arrangement
    {
        int numSequences;
        int currSequenceIdx;
        Sequence sequences[MAX_ARRANGEMENT_SIZE];
        bool completed;

    public:
        void Reset(Icon *icons);
        void Spawn(void);
    };
};

__asm__(".equ Reset__Q213IconChallenge8Sequence, 0x00260D98");
__asm__(".equ PushTask__Q213IconChallenge8SequencePQ213IconChallenge4IconQ313IconChallenge4Task4TYPE, 0x00260ED0");
__asm__(".equ Spawn__Q213IconChallenge11Arrangement, 0x00260C90");

void IconChallenge::Arrangement::Reset(Icon *icons)
{
    for (int i = 0; i < MAX_ARRANGEMENT_SIZE; i++)
        sequences[i].Reset();

    currSequenceIdx = 0;
    numSequences = 4;
    sequences[0].PushTask(&icons[9], Task::TYPE_FACE_SPIN);
    sequences[0].PushTask(&icons[1], Task::TYPE_AIR_GRAB);

    sequences[1].PushTask(&icons[8], Task::TYPE_FACE_SPIN);
    sequences[1].PushTask(&icons[12], Task::TYPE_TUBE_TIME_10);
    sequences[1].PushTask(&icons[15], Task::TYPE_TUBE_TRICK);

    sequences[2].PushTask(&icons[7], Task::TYPE_AIR_SPECIAL);
    sequences[2].PushTask(&icons[1], Task::TYPE_AIR_GRAB);

    sequences[3].PushTask(&icons[2], Task::TYPE_AIR_GRAB);
    sequences[3].PushTask(&icons[11], Task::TYPE_AIR_SPIN);
    sequences[3].PushTask(&icons[4], Task::TYPE_AIR_POINTS_1000);
    sequences[3].PushTask(&icons[10], Task::TYPE_FACE_SPIN);

    completed = false;

    Spawn();
}
